#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define OLED_W 128
#define OLED_H 64
Adafruit_SSD1306 display(OLED_W, OLED_H, &Wire, -1);

// Пины по схеме
const int PIN_SOIL = D2; // GPIO4 ADC - емкостный датчик AOUT (делитель: датчик питается от 3.3В, на выходе ~0-3В)
const int PIN_LED_RED = D10; // GPIO10
const int PIN_LED_GREEN = D3; // GPIO5
const int PIN_LED_BLUE = D6; // GPIO21 (TX)
const int PIN_BUZZER = D7; // GPIO20 (RX) через NPN
const int PIN_BTN = D1; // GPIO3, кнопка на GND (внутренняя подтяжка)

// Калибровка: подобрать под грунт. Сухой воздух ~ 2800, в воде ~ 1200 (для данного датчика)
int VAL_DRY = 2600;
int VAL_WET = 1300;
int THRESH_DRY = 30; // % ниже - сухо
int THRESH_WET = 70; // % выше - влажно

unsigned long lastMeasure = 0;
bool buzzerMuted = false;
unsigned long muteUntil = 0;

int readMoisturePercent() {
  long sum=0;
  for(int i=0;i<16;i++){ sum+=analogRead(PIN_SOIL); delay(5); }
  int raw = sum/16;
  // raw выше когда сухо, ниже когда влажно -> инвертируем
  int pct = map(raw, VAL_DRY, VAL_WET, 0, 100);
  pct = constrain(pct, 0, 100);
  return pct;
}

void updateLeds(int pct){
  digitalWrite(PIN_LED_RED, pct < THRESH_DRY ? HIGH : LOW);
  digitalWrite(PIN_LED_GREEN, (pct >= THRESH_DRY && pct <= THRESH_WET) ? HIGH : LOW);
  digitalWrite(PIN_LED_BLUE, pct > THRESH_WET ? HIGH : LOW);
}

void setup(){
  pinMode(PIN_LED_RED, OUTPUT);
  pinMode(PIN_LED_GREEN, OUTPUT);
  pinMode(PIN_LED_BLUE, OUTPUT);
  pinMode(PIN_BUZZER, OUTPUT);
  pinMode(PIN_BTN, INPUT_PULLUP);
  pinMode(PIN_SOIL, INPUT);
  digitalWrite(PIN_BUZZER, LOW);

  Wire.begin(); // SDA=D4 GPIO6, SCL=D5 GPIO7 на XIAO ESP32-C3
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.clearDisplay();
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0,10);
  display.println("Datchik vlazhnosti");
  display.println("Zapusk...");
  display.display();
  delay(1000);
}

void loop(){
  // кнопка: короткое нажатие - измерить сейчас и приглушить на 1ч
  if(digitalRead(PIN_BTN)==LOW){
    delay(50);
    if(digitalRead(PIN_BTN)==LOW){
      buzzerMuted = true;
      muteUntil = millis() + 3600000UL;
      // писк подтверждения
      digitalWrite(PIN_BUZZER, HIGH); delay(120); digitalWrite(PIN_BUZZER, LOW);
      while(digitalRead(PIN_BTN)==LOW) delay(10);
      lastMeasure = 0; // форсировать измерение
    }
  }
  if(buzzerMuted && millis() > muteUntil) buzzerMuted = false;

  if(millis() - lastMeasure > 5000){
    lastMeasure = millis();
    int pct = readMoisturePercent();
    updateLeds(pct);
    bool isDry = pct < THRESH_DRY;
    bool isWet = pct > THRESH_WET;

    display.clearDisplay();
    display.setTextSize(2);
    display.setCursor(0,0);
    display.print(pct); display.print(" %");
    display.setTextSize(1);
    display.setCursor(0,22);
    if(isDry) display.println("SUHO - POLEI!");
    else if(isWet) display.println("Vlazhno - OK");
    else display.println("Normalno");
    display.setCursor(0,36);
    display.print("Syro: "); display.print(analogRead(PIN_SOIL));
    display.setCursor(0,48);
    if(buzzerMuted) display.print("Zvuk: pauza 1h");
    else display.print(isDry ? "Zvuk: signal!" : "Zvuk: tikho");
    display.display();

    if(isDry && !buzzerMuted){
      // 3 коротких писка
      for(int i=0;i<3;i++){ digitalWrite(PIN_BUZZER,HIGH); delay(200); digitalWrite(PIN_BUZZER,LOW); delay(200); }
    }
    // глубокий сон можно включить раскомментировав (проснется по кнопке D1):
    // esp_sleep_enable_ext1_wakeup(1ULL<<3, ESP_EXT1_WAKEUP_ALL_LOW); esp_deep_sleep(10*60*1000000ULL);
  }
}
